import type { CourseQuestion, CourseUnit } from "./course/courseTypes";
import type { LearningProfile } from "../personalized/profile";
import { ITALIAN_WORLDS } from "./worlds";

export const ITALIAN_PASSAGE_QUESTION_COUNT = 5;
export const ITALIAN_PASSAGE_MIN_CORRECT = 4;

/**
 * One optional independent placement check per world boundary.
 * These questions are sampled from the four prerequisite cities' existing
 * reviewed exams, never from the target world or generated by AI at runtime.
 * The player sees each distinct question once per attempt.
 */
export type ItalianWorldPassage = {
  id: string;
  sourceWorldId: string;
  targetWorldId: string;
  targetUnitId: string;
  questions: CourseQuestion[];
};

export type ItalianPassageAnswer = { questionId: string; correct: boolean; assisted: boolean };

export function buildItalianWorldPassages(units: readonly CourseUnit[]): ItalianWorldPassage[] {
  const byId = new Map(units.map(unit => [unit.id, unit]));
  return ITALIAN_WORLDS.slice(0, -1).flatMap((world, index) => {
    const next = ITALIAN_WORLDS[index + 1];
    const sourceUnits = world.cities.map(city => byId.get(city.unitId));
    if (!next || sourceUnits.some(unit => !unit)) return [];
    const questions: CourseQuestion[] = [];
    const used = new Set<string>();
    // Draw from all four cities, not only the beginning of the language.
    for (const unit of sourceUnits) {
      const found = unit!.quiz.questions.find(question => !used.has(question.id) && question.kind !== "culture");
      if (found) { questions.push(found); used.add(found.id); }
    }
    // Add one more different question, preferably from the final city.
    for (const unit of [...sourceUnits].reverse()) {
      for (const question of unit!.quiz.questions) {
        if (questions.length >= ITALIAN_PASSAGE_QUESTION_COUNT) break;
        if (used.has(question.id) || question.kind === "culture") continue;
        questions.push(question); used.add(question.id);
      }
      if (questions.length === ITALIAN_PASSAGE_QUESTION_COUNT) break;
    }
    if (questions.length !== ITALIAN_PASSAGE_QUESTION_COUNT) return [];
    return [{ id: `italian-passage:${world.id}:${next.id}`, sourceWorldId: world.id,
      targetWorldId: next.id, targetUnitId: next.cities[0].unitId, questions }];
  });
}

/** A knowledge check is not a city examination and does not issue a stamp. */
export function evaluateItalianWorldPassage(
  passage: ItalianWorldPassage,
  answers: readonly ItalianPassageAnswer[],
): { complete: boolean; correct: number; assisted: boolean; passed: boolean } {
  const complete = passage.questions.length === ITALIAN_PASSAGE_QUESTION_COUNT &&
    answers.length === ITALIAN_PASSAGE_QUESTION_COUNT &&
    answers.every((answer, index) => answer.questionId === passage.questions[index]?.id &&
      typeof answer.correct === "boolean" && typeof answer.assisted === "boolean");
  const correct = complete ? answers.filter(answer => answer.correct).length : 0;
  const assisted = complete ? answers.some(answer => answer.assisted) : false;
  return { complete, correct, assisted, passed: complete && !assisted && correct >= ITALIAN_PASSAGE_MIN_CORRECT };
}

/**
 * This changes an existing, locally editable learning *starting preference*.
 * It grants zero badges, Passes, mastery, credits, purchases or server rights.
 * Any paid/unreleased course content must continue to enforce its own gates.
 */
export function profileAfterItalianWorldPassage(
  profile: LearningProfile,
  passage: ItalianWorldPassage,
  orderedUnitIds: readonly string[],
  now: number,
): LearningProfile | null {
  const from = orderedUnitIds.indexOf(profile.startUnitId);
  const to = orderedUnitIds.indexOf(passage.targetUnitId);
  const expected = ITALIAN_WORLDS.findIndex(world => world.id === passage.sourceWorldId);
  if (profile.language !== "it" || expected < 0 || expected >= ITALIAN_WORLDS.length - 1 ||
    ITALIAN_WORLDS[expected + 1].id !== passage.targetWorldId ||
    ITALIAN_WORLDS[expected + 1].cities[0]?.unitId !== passage.targetUnitId ||
    from < 0 || to <= from || !Number.isFinite(now) || now < 0) return null;
  return { ...profile, startUnitId: passage.targetUnitId, placement: "check", updatedAt: now };
}
